  'advertiser_faq1_a': 'ઝુંબેશ પર જાઓ અને "ઝુંબેશ બનાવો" પર ટેપ કરો. મૂળભૂત માહિતી દાખલ કરવા, તમારી 16:9 ક્રિએટિવ સામગ્રી અપલોડ કરવા, લક્ષિત કાફલો પસંદ કરવા, સમયપત્રક અને બજેટ ગોઠવવા અને ચકાસણી માટે સબમિટ કરવા માટે પગલાવાર સેટઅપ અનુસરો.',
  'advertiser_faq1_q': 'ટ્રાન્ઝિટ જાહેરાત ઝુંબેશ કેવી રીતે બનાવવી અને લોન્ચ કરવી?',
  'advertiser_faq2_a': 'અમે MP4 (H.264), JPG, PNG અને HTML5 ઝિપ પેકેજોને સપોર્ટ કરીએ છીએ. માનક રિઝોલ્યુશન 1920×1080 (16:9 પાસા ગુણોત્તર) છે, વિડિઓ જાહેરાતો માટે મહત્તમ અવધિ 30 સેકન્ડ છે, અને ફાઇલનું કદ 50 MB થી ઓછું હોવું આવશ્યક છે.',
  'advertiser_faq2_q': 'ભલામણ કરેલ ક્રિએટિવ વિશિષ્ટતાઓ શું છે?',
  'advertiser_faq3_a': 'દરેક ઝુંબેશ એક ટ્રેક કરી શકાય તેવી QR ઓળખ જનરેટ કરે છે. જ્યારે મુસાફરો સ્ક્રીન પર પ્રદર્શિત QR કોડ સ્કેન કરે છે, ત્યારે સિસ્ટમ સમય, સ્થાન, વાહન ID રેકોર્ડ કરે છે અને તેમને તમારા લેન્ડિંગ પેજ પર રીડાયરેક્ટ કરે છે.',
  'advertiser_faq3_q': 'સ્માર્ટ QR કોડ લીડ એટ્રિબ્યુશન કેવી રીતે કાર્ય કરે છે?',
  'advertiser_faq4_a': 'ઝુંબેશ માટે દૈનિક અથવા કુલ બજેટ મોડેલ પર શુલ્ક લેવામાં આવે છે. જાહેરાત ખર્ચ પર GST (18%) ગણવામાં આવે છે. ચકાસણી મંજૂરી પર ટેક્સ ક્રેડિટ સાથેના ઇનવોઇસ આપમેળે જનરેટ થાય છે.',
