  'gov_help.faq2_a': 'તમામ સક્રિય મ્યુનિસિપલ રૂટ પર જીપીએસ, સ્માર્ટ ટિકિટિંગ અને સ્ટોપ કેમેરા સેન્સરમાંથી દર 60 સેકન્ડે મુસાફરોનો લોડ ટેલિમેટ્રી એકત્રિત કરવામાં આવે છે.',
  'gov_help.faq3_q': 'રાજ્ય ઓડિટ માટે વૈધાનિક પાલન લોગ કેવી રીતે નિકાસ કરવા?',
  'gov_help.faq3_a': 'પાલન અહેવાલો પર નેવિગેટ કરો, ઓડિટ તારીખ શ્રેણી પસંદ કરો અને છેડછાડ-પ્રૂફ SHA-256 હસ્તાક્ષરિત CSV અથવા PDF ઓડિટ બંડલ નિકાસ કરો.',
  'gov_help.faq4_q': 'વાણિજ્યિક જાહેરાત ડિસ્પ્લે માટે જરૂરી સુરક્ષા ધોરણો શું છે?',
  'gov_help.faq4_a': 'તમામ ટ્રાન્ઝિટ ડિસ્પ્લે રાત્રિના પરિવહન દરમિયાન ફરજિયાત ઓટો-ડિમિંગ સાથે ઓટોમોટિવ વાઇબ્રેશન (ISO 16750) અને જ્યોત-રિટાડન્ટ સલામતી ધોરણોનું પાલન કરે છે.',
